package sandbox

import (
	"context"
	"reflect"
	"strings"
	"time"

	"github.com/sandbox-kit/kit/sdks/go/internal/sdk"
	"google.golang.org/protobuf/proto"
)

// Filesystem reads and writes files inside one sandbox.
// Obtain it from Sandbox.Filesystem. Paths in the sandbox are absolute.
// A nil timeout inherits Config.Timeout. Explicit zero adds no Kit deadline.
type Filesystem struct {
	owner *Sandbox
}

// Filesystem returns the file operations for this sandbox.
// A nil handle returns nil.
func (s *Sandbox) Filesystem() *Filesystem {
	if s == nil {
		return nil
	}
	return &Filesystem{owner: s}
}

// ReadFile returns the bytes of the file at path.
// path is absolute. A nil context returns ErrorKindInvalidArgument.
func (f *Filesystem) ReadFile(ctx context.Context, path string, options *FileReadOptions) ([]byte, error) {
	var data []byte
	err := f.call(ctx, "read_file", options.GetTimeout(), path, "", func(operationContext context.Context, id string) error {
		files, err := f.files("read_file")
		if err != nil {
			return err
		}
		data, err = files.ReadFile(operationContext, id, path, cloneMessage(options))
		return err
	})
	return data, err
}

// WriteFile replaces the file at path with data and creates missing parent directories.
// path is absolute. A nil context returns ErrorKindInvalidArgument.
func (f *Filesystem) WriteFile(ctx context.Context, path string, data []byte, options *FileWriteOptions) error {
	return f.call(ctx, "write_file", options.GetTimeout(), path, "", func(operationContext context.Context, id string) error {
		files, err := f.files("write_file")
		if err != nil {
			return err
		}
		return files.WriteFile(operationContext, id, path, data, cloneMessage(options))
	})
}

// CopyFromLocal copies the file at localPath into remotePath.
// remotePath is absolute. localPath is a path on the caller's machine.
func (f *Filesystem) CopyFromLocal(ctx context.Context, localPath, remotePath string, options *FileCopyOptions) error {
	return f.call(ctx, "copy_from_local", options.GetTimeout(), remotePath, localPath, func(operationContext context.Context, id string) error {
		files, err := f.files("copy_from_local")
		if err != nil {
			return err
		}
		return files.CopyFromLocal(operationContext, id, localPath, remotePath, cloneMessage(options))
	})
}

// CopyToLocal copies the file at remotePath to localPath.
// remotePath is absolute. localPath is a path on the caller's machine.
func (f *Filesystem) CopyToLocal(ctx context.Context, remotePath, localPath string, options *FileCopyOptions) error {
	return f.call(ctx, "copy_to_local", options.GetTimeout(), remotePath, localPath, func(operationContext context.Context, id string) error {
		files, err := f.files("copy_to_local")
		if err != nil {
			return err
		}
		return files.CopyToLocal(operationContext, id, remotePath, localPath, cloneMessage(options))
	})
}

// MakeDirectory creates the directory at path and any missing parents.
// path is absolute. A nil context returns ErrorKindInvalidArgument.
func (f *Filesystem) MakeDirectory(ctx context.Context, path string, options *MakeDirectoryOptions) error {
	return f.call(ctx, "make_directory", options.GetTimeout(), path, "", func(operationContext context.Context, id string) error {
		files, err := f.files("make_directory")
		if err != nil {
			return err
		}
		return files.MakeDirectory(operationContext, id, path, cloneMessage(options))
	})
}

// ListDirectory lists the entries in the directory at path.
// path is absolute. The result is one directory level.
func (f *Filesystem) ListDirectory(ctx context.Context, path string, options *ListDirectoryOptions) ([]*FileInfo, error) {
	var entries []*FileInfo
	err := f.call(ctx, "list_directory", options.GetTimeout(), path, "", func(operationContext context.Context, id string) error {
		files, err := f.files("list_directory")
		if err != nil {
			return err
		}
		entries, err = files.ListDirectory(operationContext, id, path, cloneMessage(options))
		return err
	})
	return entries, err
}

// Stat returns metadata for path.
// path is absolute. A symlink result describes the symlink.
func (f *Filesystem) Stat(ctx context.Context, path string, options *StatOptions) (*FileInfo, error) {
	var info *FileInfo
	err := f.call(ctx, "stat", options.GetTimeout(), path, "", func(operationContext context.Context, id string) error {
		files, err := f.files("stat")
		if err != nil {
			return err
		}
		info, err = files.Stat(operationContext, id, path, cloneMessage(options))
		return err
	})
	if err != nil {
		return nil, err
	}
	return cloneMessage(info), nil
}

// Remove deletes the file at path.
// Set RemoveOptions.Recursive with Value(true) to delete a directory and its contents.
// An omitted recursive flag removes a file or an empty directory.
func (f *Filesystem) Remove(ctx context.Context, path string, options *RemoveOptions) error {
	return f.call(ctx, "remove", options.GetTimeout(), path, "", func(operationContext context.Context, id string) error {
		files, err := f.files("remove")
		if err != nil {
			return err
		}
		return files.Remove(operationContext, id, path, cloneMessage(options))
	})
}

func (f *Filesystem) call(ctx context.Context, operation string, timeout *time.Duration, sandboxPath, localPath string, invoke func(context.Context, string) error) error {
	owner := f.owner
	if owner == nil {
		if ctx == nil {
			return NewError(&ErrorInfo{Kind: ErrorKindInvalidArgument, Operation: operation, Field: "context", Message: "sandbox-kit: context is required"}, nil)
		}
		return NewError(&ErrorInfo{Kind: ErrorKindFailedPrecondition, Operation: operation, Message: "sandbox-kit: sandbox handle is not initialized"}, nil)
	}
	if err := absoluteSandboxPath(owner, operation, sandboxPath); err != nil {
		return err
	}
	if localPath != "" || operation == "copy_from_local" || operation == "copy_to_local" {
		if err := callerPath(owner, operation, localPath); err != nil {
			return err
		}
	}
	operationContext, cancel, id, err := owner.operationContext(ctx, operation, sdk.OptionalDuration(timeout))
	if err != nil {
		return err
	}
	defer cancel()
	if err := invoke(operationContext, id); err != nil {
		return sdk.WithErrorContext(err, owner.ProviderName(), operation)
	}
	return nil
}

func (f *Filesystem) files(operation string) (SandboxFiles, error) {
	files, ok := f.owner.operations.(SandboxFiles)
	if !ok {
		return nil, f.owner.unsupported(operation)
	}
	return files, nil
}

func absoluteSandboxPath(owner *Sandbox, operation, path string) error {
	if path == "" || !strings.HasPrefix(path, "/") || strings.ContainsRune(path, 0) {
		return NewError(&ErrorInfo{
			Kind:      ErrorKindInvalidArgument,
			Provider:  owner.ProviderName(),
			Operation: operation,
			Field:     FileFieldPath,
			Message:   "sandbox-kit: sandbox path must be absolute",
		}, nil)
	}
	return nil
}

func callerPath(owner *Sandbox, operation, path string) error {
	if path == "" || strings.ContainsRune(path, 0) {
		return NewError(&ErrorInfo{
			Kind:      ErrorKindInvalidArgument,
			Provider:  owner.ProviderName(),
			Operation: operation,
			Field:     FileFieldLocalPath,
			Message:   "sandbox-kit: local path is required",
		}, nil)
	}
	return nil
}

func cloneMessage[T proto.Message](message T) T {
	value := reflect.ValueOf(message)
	if !value.IsValid() || (value.Kind() == reflect.Pointer && value.IsNil()) {
		return message
	}
	cloned, _ := proto.Clone(message).(T)
	return cloned
}

package daytona

import (
	"context"

	daytona "github.com/daytona/clients/sdk-go/pkg/daytona"
	"github.com/daytona/clients/sdk-go/pkg/types"
	"github.com/sandbox-kit/kit/sdks/go/internal/sdk"
	"github.com/sandbox-kit/kit/sdks/go/sandbox"
	"google.golang.org/protobuf/types/known/timestamppb"
	durationpb "google.golang.org/protobuf/types/known/durationpb"
)

var _ sandbox.SandboxFiles = (*backend)(nil)

func (b *backend) ReadFile(ctx context.Context, id, path string, options *sandbox.FileReadOptions) ([]byte, error) {
	if err := wholeSecondFileTimeout("read_file", options.GetTimeout()); err != nil {
		return nil, err
	}
	instance, err := b.fileSandbox(ctx, id, "read_file")
	if err != nil {
		return nil, err
	}
	data, err := instance.FileSystem.DownloadFile(ctx, path, nil)
	if err != nil {
		return nil, mapProviderError(err, "read_file")
	}
	return data, nil
}

func (b *backend) WriteFile(ctx context.Context, id, path string, data []byte, options *sandbox.FileWriteOptions) error {
	if err := wholeSecondFileTimeout("write_file", options.GetTimeout()); err != nil {
		return err
	}
	instance, err := b.fileSandbox(ctx, id, "write_file")
	if err != nil {
		return err
	}
	if data == nil {
		data = []byte{}
	}
	if err := instance.FileSystem.UploadFile(ctx, data, path); err != nil {
		return mapProviderError(err, "write_file")
	}
	return nil
}

func (b *backend) CopyFromLocal(ctx context.Context, id, localPath, remotePath string, options *sandbox.FileCopyOptions) error {
	if err := wholeSecondFileTimeout("copy_from_local", options.GetTimeout()); err != nil {
		return err
	}
	instance, err := b.fileSandbox(ctx, id, "copy_from_local")
	if err != nil {
		return err
	}
	if err := instance.FileSystem.UploadFile(ctx, localPath, remotePath); err != nil {
		return mapProviderError(err, "copy_from_local")
	}
	return nil
}

func (b *backend) CopyToLocal(ctx context.Context, id, remotePath, localPath string, options *sandbox.FileCopyOptions) error {
	if err := wholeSecondFileTimeout("copy_to_local", options.GetTimeout()); err != nil {
		return err
	}
	instance, err := b.fileSandbox(ctx, id, "copy_to_local")
	if err != nil {
		return err
	}
	if _, err := instance.FileSystem.DownloadFile(ctx, remotePath, &localPath); err != nil {
		return mapProviderError(err, "copy_to_local")
	}
	return nil
}

func (b *backend) MakeDirectory(ctx context.Context, id, path string, options *sandbox.MakeDirectoryOptions) error {
	if err := wholeSecondFileTimeout("make_directory", options.GetTimeout()); err != nil {
		return err
	}
	instance, err := b.fileSandbox(ctx, id, "make_directory")
	if err != nil {
		return err
	}
	if err := instance.FileSystem.CreateFolder(ctx, path); err != nil {
		return mapProviderError(err, "make_directory")
	}
	return nil
}

func (b *backend) ListDirectory(ctx context.Context, id, path string, options *sandbox.ListDirectoryOptions) ([]*sandbox.FileInfo, error) {
	if err := wholeSecondFileTimeout("list_directory", options.GetTimeout()); err != nil {
		return nil, err
	}
	instance, err := b.fileSandbox(ctx, id, "list_directory")
	if err != nil {
		return nil, err
	}
	entries, err := instance.FileSystem.ListFiles(ctx, path)
	if err != nil {
		return nil, mapProviderError(err, "list_directory")
	}
	result := make([]*sandbox.FileInfo, 0, len(entries))
	for _, entry := range entries {
		info, err := daytonaFileInfo(entry, "list_directory")
		if err != nil {
			return nil, err
		}
		result = append(result, info)
	}
	return result, nil
}

func (b *backend) Stat(ctx context.Context, id, path string, options *sandbox.StatOptions) (*sandbox.FileInfo, error) {
	if err := wholeSecondFileTimeout("stat", options.GetTimeout()); err != nil {
		return nil, err
	}
	instance, err := b.fileSandbox(ctx, id, "stat")
	if err != nil {
		return nil, err
	}
	info, err := instance.FileSystem.GetFileInfo(ctx, path)
	if err != nil {
		return nil, mapProviderError(err, "stat")
	}
	return daytonaFileInfo(info, "stat")
}

func (b *backend) Remove(ctx context.Context, id, path string, options *sandbox.RemoveOptions) error {
	if err := wholeSecondFileTimeout("remove", options.GetTimeout()); err != nil {
		return err
	}
	instance, err := b.fileSandbox(ctx, id, "remove")
	if err != nil {
		return err
	}
	recursive := options != nil && options.GetRecursive()
	if err := instance.FileSystem.DeleteFile(ctx, path, recursive); err != nil {
		return mapProviderError(err, "remove")
	}
	return nil
}

func (b *backend) fileSandbox(ctx context.Context, id, operation string) (*daytona.Sandbox, error) {
	instance, err := b.nativeSandbox(ctx, id)
	if err != nil {
		return nil, mapProviderError(err, operation)
	}
	if instance == nil || instance.FileSystem == nil {
		return nil, sandbox.NewError(&sandbox.ErrorInfo{
			Kind:      sandbox.ErrorKindInvalidResponse,
			Provider:  "daytona",
			Operation: operation,
			Message:   "sandbox-kit daytona: SDK returned no filesystem",
		}, nil)
	}
	return instance, nil
}

func wholeSecondFileTimeout(operation string, value *durationpb.Duration) error {
	timeout := sdk.OptionalDuration(value)
	if timeout == nil {
		return nil
	}
	if *timeout%time.Second != 0 {
		return sandbox.NewError(&sandbox.ErrorInfo{
			Kind:      sandbox.ErrorKindInvalidArgument,
			Provider:  "daytona",
			Operation: operation,
			Field:     sandbox.ConfigFieldTimeout,
			Message:   "sandbox-kit daytona: timeout must be a whole number of seconds",
		}, nil)
	}
	return nil
}

func daytonaFileInfo(info *types.FileInfo, operation string) (*sandbox.FileInfo, error) {
	if info == nil {
		return nil, sandbox.NewError(&sandbox.ErrorInfo{
			Kind:      sandbox.ErrorKindInvalidResponse,
			Provider:  "daytona",
			Operation: operation,
			Field:     sandbox.FileFieldPath,
			Message:   "sandbox-kit daytona: SDK returned no file metadata",
		}, nil)
	}
	kind := sandbox.FileTypeFile
	if info.IsDirectory {
		kind = sandbox.FileTypeDirectory
	}
	result := &sandbox.FileInfo{
		Name: info.Name,
		Path: info.Path,
		Type: kind,
		Size: info.Size,
	}
	if info.Mode != "" {
		result.Mode = sandbox.Value(info.Mode)
	}
	if !info.ModifiedTime.IsZero() {
		result.ModifiedAt = timestamppb.New(info.ModifiedTime)
	}
	return result, nil
}

package modal

import (
	"context"
	"errors"
	"fmt"
	"math"
	"os"
	"time"

	sdk "github.com/modal-labs/modal-client/go"
	"github.com/sandbox-kit/kit/sdks/go/sandbox"
	"google.golang.org/protobuf/types/known/timestamppb"
)

var _ sandbox.SandboxFiles = (*backend)(nil)

func (b *backend) ReadFile(ctx context.Context, id, path string, _ *sandbox.FileReadOptions) ([]byte, error) {
	instance, err := b.fileSandbox(ctx, id, "read_file")
	if err != nil {
		return nil, err
	}
	data, err := instance.Filesystem.ReadBytes(ctx, path, nil)
	if err != nil {
		return nil, mapFileError(err, "read_file", "")
	}
	return data, nil
}

func (b *backend) WriteFile(ctx context.Context, id, path string, data []byte, _ *sandbox.FileWriteOptions) error {
	instance, err := b.fileSandbox(ctx, id, "write_file")
	if err != nil {
		return err
	}
	if data == nil {
		data = []byte{}
	}
	if err := instance.Filesystem.WriteBytes(ctx, data, path, nil); err != nil {
		return mapFileError(err, "write_file", "")
	}
	return nil
}

func (b *backend) CopyFromLocal(ctx context.Context, id, localPath, remotePath string, _ *sandbox.FileCopyOptions) error {
	instance, err := b.fileSandbox(ctx, id, "copy_from_local")
	if err != nil {
		return err
	}
	if err := instance.Filesystem.CopyFromLocal(ctx, localPath, remotePath, nil); err != nil {
		return mapFileError(err, "copy_from_local", sandbox.FileFieldLocalPath)
	}
	return nil
}

func (b *backend) CopyToLocal(ctx context.Context, id, remotePath, localPath string, _ *sandbox.FileCopyOptions) error {
	instance, err := b.fileSandbox(ctx, id, "copy_to_local")
	if err != nil {
		return err
	}
	if err := instance.Filesystem.CopyToLocal(ctx, remotePath, localPath, nil); err != nil {
		return mapFileError(err, "copy_to_local", sandbox.FileFieldLocalPath)
	}
	return nil
}

func (b *backend) MakeDirectory(ctx context.Context, id, path string, _ *sandbox.MakeDirectoryOptions) error {
	instance, err := b.fileSandbox(ctx, id, "make_directory")
	if err != nil {
		return err
	}
	createParents := true
	if err := instance.Filesystem.MakeDirectory(ctx, path, &sdk.SandboxFilesystemMakeDirectoryParams{CreateParents: &createParents}); err != nil {
		return mapFileError(err, "make_directory", "")
	}
	return nil
}

func (b *backend) ListDirectory(ctx context.Context, id, path string, _ *sandbox.ListDirectoryOptions) ([]*sandbox.FileInfo, error) {
	instance, err := b.fileSandbox(ctx, id, "list_directory")
	if err != nil {
		return nil, err
	}
	entries, err := instance.Filesystem.ListFiles(ctx, path, nil)
	if err != nil {
		return nil, mapFileError(err, "list_directory", "")
	}
	result := make([]*sandbox.FileInfo, 0, len(entries))
	for _, entry := range entries {
		result = append(result, modalFileInfo(entry))
	}
	return result, nil
}

func (b *backend) Stat(ctx context.Context, id, path string, _ *sandbox.StatOptions) (*sandbox.FileInfo, error) {
	instance, err := b.fileSandbox(ctx, id, "stat")
	if err != nil {
		return nil, err
	}
	info, err := instance.Filesystem.Stat(ctx, path, nil)
	if err != nil {
		return nil, mapFileError(err, "stat", "")
	}
	if info == nil {
		return nil, sandbox.NewError(&sandbox.ErrorInfo{
			Kind:      sandbox.ErrorKindInvalidResponse,
			Provider:  "modal",
			Operation: "stat",
			Field:     sandbox.FileFieldPath,
			Message:   "sandbox-kit modal: SDK returned no file metadata",
		}, nil)
	}
	return modalFileInfo(*info), nil
}

func (b *backend) Remove(ctx context.Context, id, path string, options *sandbox.RemoveOptions) error {
	instance, err := b.fileSandbox(ctx, id, "remove")
	if err != nil {
		return err
	}
	recursive := options != nil && options.GetRecursive()
	if err := instance.Filesystem.Remove(ctx, path, &sdk.SandboxFilesystemRemoveParams{Recursive: recursive}); err != nil {
		return mapFileError(err, "remove", "")
	}
	return nil
}

func (b *backend) fileSandbox(ctx context.Context, id, operation string) (*sdk.Sandbox, error) {
	instance, err := b.client.Sandboxes.FromID(ctx, id, nil)
	if err != nil {
		return nil, mapProviderError(err, operation)
	}
	if instance == nil || instance.Filesystem == nil {
		return nil, sandbox.NewError(&sandbox.ErrorInfo{
			Kind:      sandbox.ErrorKindInvalidResponse,
			Provider:  "modal",
			Operation: operation,
			Message:   "sandbox-kit modal: SDK returned no filesystem",
		}, nil)
	}
	return instance, nil
}

func mapFileError(err error, operation, localField string) error {
	if err == nil {
		return nil
	}
	var pathError *os.PathError
	if errors.As(err, &pathError) {
		kind := sandbox.ErrorKindInvalidArgument
		if errors.Is(pathError.Err, os.ErrNotExist) {
			kind = sandbox.ErrorKindNotFound
		}
		field := localField
		if field == "" {
			field = sandbox.FileFieldLocalPath
		}
		return sandbox.NewError(&sandbox.ErrorInfo{
			Kind:      kind,
			Provider:  "modal",
			Operation: operation,
			Field:     field,
			Message:   err.Error(),
		}, err)
	}
	return mapProviderError(err, operation)
}

func modalFileInfo(info sdk.FileInfo) *sandbox.FileInfo {
	kind := sandbox.FileTypeFile
	switch info.Type {
	case sdk.FileTypeDirectory:
		kind = sandbox.FileTypeDirectory
	case sdk.FileTypeSymlink:
		kind = sandbox.FileTypeSymlink
	}
	result := &sandbox.FileInfo{
		Name: info.Name,
		Path: info.Path,
		Type: kind,
		Size: info.Size,
		Mode: sandbox.Value(fmt.Sprintf("%04o", info.Mode&0o7777)),
	}
	if info.Permissions != "" {
		result.Permissions = sandbox.Value(info.Permissions)
	}
	if info.Owner != "" {
		result.Owner = sandbox.Value(info.Owner)
	}
	if info.Group != "" {
		result.Group = sandbox.Value(info.Group)
	}
	if info.SymlinkTarget != nil && *info.SymlinkTarget != "" {
		result.SymlinkTarget = info.SymlinkTarget
	}
	if !math.IsNaN(info.ModifiedTime) && !math.IsInf(info.ModifiedTime, 0) {
		whole := int64(info.ModifiedTime)
		frac := info.ModifiedTime - float64(whole)
		result.ModifiedAt = timestamppb.New(time.Unix(whole, int64(frac*1e9)).UTC())
	}
	return result
}

