		t.Fatalf("unexpected error: %v", err)
	}
}

func TestFilesystemUnsupportedWithoutCapability(t *testing.T) {
	client, err := sandbox.NewClient(&lifecycleProvider{backend: &lifecycleBackend{}}, &sandbox.Config{})
	if err != nil {
