await sandbox.filesystem.makeDirectory("/tmp/kit-files");
await sandbox.filesystem.writeFile(remote, new TextEncoder().encode("hello\n"));
const data = await sandbox.filesystem.readFile(remote);
const info = await sandbox.filesystem.stat(remote);
const entries = await sandbox.filesystem.listDirectory("/tmp/kit-files");
await sandbox.filesystem.copyToLocal(remote, "note.txt");
await sandbox.filesystem.copyFromLocal("note.txt", "/tmp/kit-files/copy.txt");
await sandbox.filesystem.remove("/tmp/kit-files", { recursive: true });
console.log(new TextDecoder().decode(data), info.size, entries.length);
```

