				Mode:  sandbox.PolicyModeAfter,
				After: sandbox.Duration(60 * time.Second),
			},
		},
		Labels: map[string]string{"example": "use-modal-files"},
	})
	if err != nil {
		return err
	}
	defer func() {
		if _, err := instance.Terminate(context.Background(), &sandbox.TerminateOptions{Wait: sandbox.Value(true)}); err != nil {
			log.Printf("terminate sandbox: %v", err)
		}
	}()
