		return err
	}
	data, err := files.ReadFile(ctx, remote, nil)
	if err != nil {
		return err
	}
	info, err := files.Stat(ctx, remote, nil)
	if err != nil {
		return err
	}
	entries, err := files.ListDirectory(ctx, remoteDir, nil)
	if err != nil {
		return err
	}
	local := filepath.Join(localDir, "note.txt")
	if err := files.CopyToLocal(ctx, remote, local, nil); err != nil {
		return err
	}
	copied, err := os.ReadFile(local)
	if err != nil {
		return err
	}
	if string(copied) != string(data) {
		return fmt.Errorf("local copy %q does not match remote %q", copied, data)
	}
	remoteCopy := remoteDir + "/copy.txt"
	if err := files.CopyFromLocal(ctx, local, remoteCopy, nil); err != nil {
		return err
	}
	if err := files.Remove(ctx, remoteCopy, nil); err != nil {
		return err
	}
	if err := files.Remove(ctx, remoteDir, &sandbox.RemoveOptions{Recursive: sandbox.Value(true)}); err != nil {
		return err
	}
	fmt.Printf("Modal files ok: %s (%d bytes, %d entries)\n", instance.ID(), info.GetSize(), len(entries))
	return nil
}

